\begin{definition}\label{def:category}
A \emph{category} $\mathcal C$ consists of a class of \emph{objects}; for any two objects $A,B$ a set $\operatorname{Hom}_{\mathcal C}(A,B)$ of \emph{morphisms} (or \emph{arrows}) from $A$ to $B$,
written $f\colon A\to B$; and for any three objects a \emph{composition} $\operatorname{Hom}(B,C)\times\operatorname{Hom}(A,B)\to\operatorname{Hom}(A,C)$, $(g,f)\mapsto g\circ f$, such that
\begin{enumerate}[label=(\roman*)]
\item composition is associative: $h\circ(g\circ f)=(h\circ g)\circ f$;
\item every object $A$ has an \emph{identity} $\mathrm{id}_A\in\operatorname{Hom}(A,A)$ with $f\circ\mathrm{id}_A=f$ and $\mathrm{id}_B\circ f=f$ for all $f\colon A\to B$.
\end{enumerate}
\end{definition}

\begin{definition}\label{def:functor}
A \emph{functor} $F\colon\mathcal C\to\mathcal D$ assigns to each object $A$ of $\mathcal C$ an object $F(A)$ of $\mathcal D$, and to each morphism $f\colon A\to B$ a morphism $F(f)\colon F(A)\to F(B)$, so that
\[F(g\circ f)=F(g)\circ F(f)\qquad\text{and}\qquad F(\mathrm{id}_A)=\mathrm{id}_{F(A)}.\]
A \emph{contravariant functor} from $\mathcal C$ to $\mathcal D$ is a functor $\mathcal C^{\mathrm{op}}\to\mathcal D$: it reverses arrows, $F(g\circ f)=F(f)\circ F(g)$.
\end{definition}

\begin{proposition}\label{prop:functoriso}
A functor maps isomorphisms to isomorphisms: $F(f^{-1})=F(f)^{-1}$.
\end{proposition}

\begin{example}[Brouwer, functorially]\label{ex:brouwer}
There is no continuous retraction $r\colon D^2\to S^1$ of the closed disc onto its boundary circle. If there were, with $i\colon S^1\to D^2$ the inclusion, $r\circ i=\mathrm{id}_{S^1}$, and applying
the functor $H_1$ gives $H_1(r)\circ H_1(i)=\mathrm{id}_{H_1(S^1)}$. But $H_1(i)$ goes through $H_1(D^2)=0$ while $H_1(S^1)\cong\Z$ (Volume~9, Chapter~6): the identity of $\Z$ would factor through
the zero group. As Volume~9 showed, this gives Brouwer's fixed point theorem, since a map $D^2\to D^2$ without fixed point yields a retraction by pushing each point away from its image to the boundary.
\end{example}

\begin{definition}\label{def:nat}
Let $F,G\colon\mathcal C\to\mathcal D$ be functors. A \emph{natural transformation} $\eta\colon F\Rightarrow G$ is a family of morphisms $\eta_A\colon F(A)\to G(A)$, one for each object $A$, such that
for every $f\colon A\to B$ the square of Figure~\ref{fig:universal} commutes:
\[G(f)\circ\eta_A=\eta_B\circ F(f).\]
It is a \emph{natural isomorphism} if every $\eta_A$ is an isomorphism; then $(\eta_A^{-1})$ is a natural transformation $G\Rightarrow F$, as one sees by composing the square with $\eta_A^{-1}$ and $\eta_B^{-1}$.
\end{definition}

\begin{example}\label{ex:nattrans}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item The quotient maps $\pi_G\colon G\to G^{\mathrm{ab}}$ form a natural transformation from the identity functor of $\mathbf{Grp}$ to abelianisation (followed by the inclusion of $\mathbf{Ab}$ in
$\mathbf{Grp}$): $f^{\mathrm{ab}}(\pi_G(g))=f(g)H'=\pi_H(f(g))$.
\item The determinant $\det_R\colon\mathrm{GL}_n(R)\to R^\times$ is natural in the commutative ring $R$: for a ring homomorphism $\varphi$, $\det(\varphi(M))=\varphi(\det M)$, because the
determinant is a polynomial with integer coefficients in the entries.
\end{enumerate}
\end{example}

\begin{theorem}[the double dual is natural]\label{thm:bidualnat}
On the category $\mathbf{FinVect}_K$ of finite-dimensional vector spaces over $K$, the maps $\iota_V$ form a natural isomorphism from the identity functor to the functor $V\mapsto V^{**}$,
$f\mapsto f^{**}$.
\end{theorem}

\begin{theorem}[$V$ is not naturally its dual]\label{thm:notnatural}
If the field $K$ has more than three elements, there is no family of isomorphisms $\eta_V\colon V\to V^*$, for $V$ in $\mathbf{Iso}_K$, satisfying \eqref{eq:dualnat}. Indeed \eqref{eq:dualnat} already fails
for every non-zero $V$ and the maps $f=\lambda\,\mathrm{id}_V$.
\end{theorem}

\begin{definition}\label{def:initial}
An object $I$ of $\mathcal C$ is \emph{initial} if for every object $X$ there is exactly one morphism $I\to X$, and \emph{terminal} if for every $X$ there is exactly one morphism $X\to I$.
\end{definition}

\begin{proposition}\label{prop:initialunique}
Two initial objects $I,I'$ are isomorphic, by a unique isomorphism. The same holds for terminal objects.
\end{proposition}

\begin{definition}\label{def:product}
A \emph{product} of two objects $A,B$ is an object $P$ with morphisms $p_A\colon P\to A$, $p_B\colon P\to B$ such that for every object $X$ and morphisms $f\colon X\to A$, $g\colon X\to B$ there is exactly one
morphism $h\colon X\to P$ with $p_A\circ h=f$ and $p_B\circ h=g$ (Figure~\ref{fig:universal}). We write $P=A\times B$ and $h=(f,g)$. A \emph{coproduct} $A\sqcup B$ is a product in $\mathcal C^{\mathrm{op}}$: morphisms
$i_A\colon A\to A\sqcup B$, $i_B\colon B\to A\sqcup B$ such that every pair $f\colon A\to X$, $g\colon B\to X$ is $h\circ i_A$, $h\circ i_B$ for exactly one $h\colon A\sqcup B\to X$.
\end{definition}

\begin{proposition}[universal property of abelianisation]\label{prop:abuniv}
Let $G$ be a group. Every homomorphism $f\colon G\to A$ to an abelian group factors as $f=\bar f\circ\pi_G$ for exactly one homomorphism $\bar f\colon G^{\mathrm{ab}}\to A$.
\end{proposition}

\begin{theorem}[Yoneda's lemma]\label{thm:yoneda}
Let $F\colon\mathcal C\to\mathbf{Set}$ be a functor and $A$ an object of $\mathcal C$. The map
\[\Phi\colon\operatorname{Nat}(h^A,F)\to F(A),\qquad\alpha\mapsto\alpha_A(\mathrm{id}_A),\]
is a bijection. Its inverse sends $x\in F(A)$ to the natural transformation $\alpha^x$ with $\alpha^x_B(f)=F(f)(x)$ for $f\colon A\to B$.
\end{theorem}

\begin{corollary}[an object is known by its maps]\label{cor:yonedaemb}
For objects $A,B$, the natural transformations $h^A\Rightarrow h^B$ are exactly the maps $-\circ u$ for $u\in\operatorname{Hom}(B,A)$, and $h^A$ and $h^B$ are naturally isomorphic if and only if $A\cong B$. Likewise,
the natural transformations $h_A\Rightarrow h_B$ are the maps $u\circ-$ for $u\in\operatorname{Hom}(A,B)$, and $h_A\cong h_B$ if and only if $A\cong B$.
\end{corollary}

\begin{example}[Cayley's theorem]\label{ex:cayley}
Let $G$ be a group, seen as a category with one object $\bullet$. A functor $F\colon G\to\mathbf{Set}$ is a set $X=F(\bullet)$ with a map $F(g)\colon X\to X$ for each $g$, such that $F(gh)=F(g)F(h)$ and $F(1)=\mathrm{id}$: a $G$-set
(Volume~3, Chapter~3). A natural transformation between two $G$-sets is a map commuting with the actions. The functor $h^\bullet$ is $G$ acting on itself by left multiplication. By Corollary~\ref{cor:yonedaemb}, the maps
$G\to G$ commuting with all left multiplications are exactly the right multiplications $x\mapsto xu$, and Theorem~\ref{thm:yoneda} with $F=h^\bullet$ shows that distinct $g$ give distinct permutations
$x\mapsto gx$ of $G$. The second statement is Cayley's theorem: every group is a group of permutations of its own elements.
\end{example}

\begin{definition}\label{def:adjunction}
Functors $F\colon\mathcal C\to\mathcal D$ and $G\colon\mathcal D\to\mathcal C$ are \emph{adjoint}, $F$ \emph{left adjoint} to $G$ and $G$ \emph{right adjoint} to $F$, written $F\dashv G$, if there are bijections
\[\varphi_{A,B}\colon\operatorname{Hom}_{\mathcal D}(F(A),B)\to\operatorname{Hom}_{\mathcal C}(A,G(B)),\]
natural in $A$ and $B$: for $a\colon A'\to A$, $b\colon B\to B'$ and $h\colon F(A)\to B$, $\varphi_{A',B'}(b\circ h\circ F(a))=G(b)\circ\varphi_{A,B}(h)\circ a$.
\end{definition}

\begin{theorem}[uniqueness of adjoints]\label{thm:adjunique}
If $G$ and $G'$ are both right adjoint to $F$, then $G\cong G'$: there is a natural isomorphism $G\Rightarrow G'$.
\end{theorem}

\begin{theorem}[right adjoints preserve products]\label{thm:rapl}
Let $F\dashv G$ and let $B_1\times B_2$ be a product in $\mathcal D$, with projections $p_1,p_2$. Then $G(B_1\times B_2)$, with the projections $G(p_1),G(p_2)$, is a product of $G(B_1)$ and $G(B_2)$ in $\mathcal C$.
\end{theorem}

\begin{exercise}[$\star$]\label{ex:zq}
Show that in $\mathbf{Ring}$ the inclusion $\Z\to\Q$ is a monomorphism and an epimorphism, but not an isomorphism. Is it an epimorphism in $\mathbf{Set}$?
\end{exercise}

\begin{exercise}[$\star$]\label{ex:nofieldproduct}
In the category of fields and ring homomorphisms, show that $\mathbb F_2$ and $\mathbb F_3$ have no product and no coproduct.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:words}
Let $U\colon\mathbf{Grp}\to\mathbf{Set}$ be the forgetful functor and $U^2\colon G\mapsto G\times G$.
\begin{enumerate}[label=(\alph*)]
\item Show that $U^2$ is represented by the free group $F_2$ on two letters $a,b$, and deduce that the natural operations $G\times G\to G$ are exactly the maps $(g,h)\mapsto w(g,h)$ for a word $w\in F_2$.
\item Under the bijection $\operatorname{Nat}(U,U)\cong\Z$ of Example~\ref{ex:natops}, which integer is inversion? What does composition of natural operations become?
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star$]\label{ex:matrixpoly}
Let $M_n\colon\mathbf{CRing}\to\mathbf{Set}$ send $R$ to the set of $n\times n$ matrices over $R$. Show that $M_n$ is represented by the polynomial ring $\Z[X_{ij}:1\le i,j\le n]$, and deduce that the families of maps
$M_n(R)\to R$ natural in $R$ are exactly the polynomials with integer coefficients in the entries. Name two of them.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:leftadj}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item Prove that a left adjoint preserves coproducts. (Avoid work: use Theorem~\ref{thm:rapl} in the opposite categories.)
\item Deduce that $R^{(S\sqcup T)}\cong R^{(S)}\oplus R^{(T)}$, and that for sets $A\times(B\sqcup C)\cong(A\times B)\sqcup(A\times C)$.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:f2plane}
Let $K=\mathbb F_2$. For a plane $V$ (a two-dimensional space over $\mathbb F_2$) and $v,w\in V$, let $\eta_V(v)(w)=1$ if $v,w$ are linearly independent and $0$ otherwise.
\begin{enumerate}[label=(\alph*)]
\item Show that $\eta_V(v)$ is a linear form, that $\eta_V\colon V\to V^*$ is a linear isomorphism, and that \eqref{eq:dualnat} holds for every isomorphism $f$ between planes.
\item Where does the proof of Theorem~\ref{thm:notnatural} break down?
\end{enumerate}
\end{exercise}

\begin{proposition}[rules of the Kronecker product]\label{linear:prop:kronecker}
Whenever the products are defined:
\begin{enumerate}[label=(\roman*)]
\item $(A\otimes B)(C\otimes D)=AC\otimes BD$ (the \emph{mixed product rule});
\item $(A\otimes B)^*=A^*\otimes B^*$, and $(A\otimes B)^{-1}=A^{-1}\otimes B^{-1}$ for invertible $A,B$;
\item if $A$ ($m\times m$) has eigenvalues $\lambda_1,\dots,\lambda_m$ and $B$ ($p\times p$) has eigenvalues $\mu_1,\dots,\mu_p$ (with
multiplicity), then $A\otimes B$ has eigenvalues $\lambda_i\mu_k$, and $A\otimes I_p+I_m\otimes B$ has eigenvalues $\lambda_i+\mu_k$;
\item $\operatorname{tr}(A\otimes B)=\operatorname{tr}A\operatorname{tr}B$, $\det(A\otimes B)=(\det A)^p(\det B)^m$, and
$\operatorname{rank}(A\otimes B)=\operatorname{rank}A\operatorname{rank}B$.
\end{enumerate}
\end{proposition}

\begin{example}[grids and cubes]\label{linear:exa:grid}
The \emph{Cartesian product} $G\mathbin\square H$ of two graphs has vertex set $V(G)\times V(H)$, with $(g,h)\sim(g',h')$ when
$g\sim g'$ and $h=h'$, or $g=g'$ and $h\sim h'$. Its adjacency matrix is $A_G\otimes I+I\otimes A_H$, so its eigenvalues are the sums
$\lambda_i(G)+\lambda_k(H)$. The $m\times n$ grid $P_m\mathbin\square P_n$ has eigenvalues $2\cos\frac{\pi i}{m+1}+2\cos\frac{\pi k}
{n+1}$ (the path $P_m$ has eigenvalues $2\cos\frac{\pi i}{m+1}$, Volume~8, Exercise~3.3); the hypercube $Q_n$, the Cartesian
product of $n$ copies of $K_2$, has the eigenvalues $\pm1\pm1\dots\pm1$, that is $n-2t$ with multiplicity $\binom nt$, as
Volume~8, Exercise~5.1 finds with characters. The same computation gives the eigenvalues of the discrete Laplacian on a rectangle, which every
numerical solver of the heat equation needs.
\end{example}

\begin{proposition}[the vec trick]\label{linear:prop:vec}
For matrices of compatible sizes, $\operatorname{vec}(AXB)=(B^{\mathsf T}\otimes A)\operatorname{vec}X$.
\end{proposition}

\begin{theorem}[Sylvester's equation]\label{linear:thm:sylvester}
Let $A\in M_m(\C)$, $B\in M_n(\C)$. The equation $AX-XB=C$ has a unique solution $X\in M_{m,n}(\C)$ for every $C$ if and only if $A$
and $B$ have no common eigenvalue.
\end{theorem}

\begin{definition}\label{linear:def:tensorrank}
The \emph{rank} $R_K(T)$ of a tensor is the least $r$ such that $T=\sum_{s=1}^ru_s\otimes v_s\otimes w_s$ with vectors over $K$.
\end{definition}

\begin{lemma}[the slice test]\label{linear:lem:slices}
Let $T\in K^2\otimes K^2\otimes K^2$ have slices $A=T_1$ and $B=T_2$, with $A$ invertible. Then $R_K(T)\le2$ if and only if $A^{-1}B$
is diagonalisable over $K$.
\end{lemma}

\begin{theorem}\label{linear:thm:bilinear}
The shortest bilinear algorithm for $n\times m$ by $m\times p$ matrix products has length $R(\langle n,m,p\rangle)$.
\end{theorem}

\begin{theorem}[the exponent of matrix multiplication]\label{linear:thm:omega}
If $R(\langle k,k,k\rangle)\le r$ with $r>k^2$, then $n\times n$ matrices can be multiplied with $O(n^{\log_kr})$ arithmetic operations.
In particular $\omega\le\log_27<2.808$, where $\omega$ is the infimum of the exponents $\tau$ for which $O(n^\tau)$ operations suffice.
\end{theorem}

\begin{exercise}[$\star$]\label{linear:ex:kroncommute}
Show that there is a permutation matrix $P$ (the \emph{commutation matrix}) such that $B\otimes A=P(A\otimes B)P^{\mathsf T}$ for all
$A\in M_m(\C)$, $B\in M_n(\C)$. Deduce that $A\otimes B$ and $B\otimes A$ have the same spectrum.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:kronnormal}
Show that $A\otimes B$ is normal (respectively Hermitian positive definite, unitary) when $A$ and $B$ are.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:roth}
Let $A\in M_m(\C)$ and $B\in M_n(\C)$ have no common eigenvalue. Show that $\bigl(\begin{smallmatrix}A&C\\0&B\end{smallmatrix}\bigr)$ is similar to
$\bigl(\begin{smallmatrix}A&0\\0&B\end{smallmatrix}\bigr)$ for every $C$.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:flattening}
Compute the flattening $\langle n,n,n\rangle_{(1)}$ and show that its rank is $n^2$. Deduce that $R(\langle n,n,n\rangle)\ge n^2$.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:strassen22}
Check the $(2,2)$ entry in Strassen's formulas, and count the additions: show that one product of size $2n$ costs $7$ products and
$18$ additions of size $n$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:strassencount}
Let $T(n)$ be the number of arithmetic operations (additions and multiplications of numbers) of Strassen's algorithm, applied
recursively down to $1\times1$ matrices, for $n=2^s$. Show that $T(n)=7n^{\log_27}-6n^2$, and compare with the $2n^3-n^2$ operations of
the schoolbook algorithm: from which $n$ on is Strassen better?
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:complexmult}
Show that the real rank of the tensor of complex multiplication (slices $\bigl(\begin{smallmatrix}1&0\\0&-1\end{smallmatrix}\bigr)$ and
$\bigl(\begin{smallmatrix}0&1\\1&0\end{smallmatrix}\bigr)$) is $3$ and its complex rank is $2$. Write the complex decomposition explicitly.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:noapprox}
Show that $W$ has no best approximation by tensors of rank at most $2$: for every tensor $S$ of rank at most $2$, $\|W-S\|>0$, while
$\inf_S\|W-S\|=0$ (Frobenius norms). Show also that $\|W_\varepsilon\|$ stays bounded but the two rank-one terms in the definition of
$W_\varepsilon$ have norm $1/\varepsilon$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:waring}
Show that $24xyz=(x+y+z)^3-(-x+y+z)^3-(x-y+z)^3-(x+y-z)^3$. Interpret this as a decomposition of the symmetric tensor
$\sum_{\text{perm}}e_1\otimes e_2\otimes e_3$ into four rank-one symmetric tensors $\ell\otimes\ell\otimes\ell$.
\end{exercise}

\begin{exercise}[$\star$]\label{linear:ex:schmidtcheck}
Find the Schmidt decomposition and the entanglement entropy of $\psi=\frac13(e_1\otimes e_1+2e_1\otimes e_2+2e_2\otimes e_1)$. Is it a
product state?
\end{exercise}

\begin{exercise}[$\star\star$]\label{linear:ex:gridlap}
The \emph{discrete Laplacian} on an $m\times n$ grid with zero boundary values is $L=L_m\otimes I_n+I_m\otimes L_n$, where $L_k$ is the
$k\times k$ tridiagonal matrix with $2$ on the diagonal and $-1$ beside it. Find its eigenvalues and its condition number, and show that
the latter grows like $n^2$ for an $n\times n$ grid.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{linear:ex:border}
Show that every tensor in $\C^2\otimes\C^2\otimes\C^2$ is a limit of tensors of rank at most $2$: the border rank of every
$2\times2\times2$ complex tensor is at most $2$. (Start with the tensors whose first slice is invertible.)
\end{exercise}

\begin{definition}\label{def:exact}
A sequence of modules and homomorphisms $\cdots\to M_{i-1}\xrightarrow{f_{i-1}}M_i\xrightarrow{f_i}M_{i+1}\to\cdots$ is \emph{exact at $M_i$} if $\operatorname{im}f_{i-1}=\ker f_i$, and \emph{exact} if it is exact
at each inner module. A \emph{short exact sequence} is an exact sequence
\[0\to A\xrightarrow{f}B\xrightarrow{g}C\to0;\]
that is, $f$ is injective, $g$ is surjective, and $\operatorname{im}f=\ker g$.
\end{definition}

\begin{example}\label{ex:ses}
The sequences $0\to\Z\xrightarrow{2}\Z\to\Z/2\to0$ and $0\to\Z/2\xrightarrow{2}\Z/4\to\Z/2\to0$ are exact and not split: $\Z$ is not isomorphic to $\Z\oplus\Z/2$, which has torsion, and $\Z/4$
not to $\Z/2\oplus\Z/2$, which has no element of order $4$. The middle term is not determined by the two ends.
\end{example}

\begin{proposition}[splitting lemma]\label{prop:split}
For a short exact sequence $0\to A\xrightarrow fB\xrightarrow gC\to0$, the following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item there is $r\colon B\to A$ with $r\circ f=\mathrm{id}_A$ (a \emph{retraction});
\item there is $s\colon C\to B$ with $g\circ s=\mathrm{id}_C$ (a \emph{section});
\item there is an isomorphism $\varphi\colon B\to A\oplus C$ with $\varphi(f(a))=(a,0)$ and $g=p_C\circ\varphi$, where $p_C$ is the projection.
\end{enumerate}
\end{proposition}

\begin{theorem}[snake lemma]\label{thm:snake}
Consider a commutative diagram of modules with exact rows $A\xrightarrow fB\xrightarrow gC\to0$ and $0\to A'\xrightarrow{f'}B'\xrightarrow{g'}C'$, and vertical maps
$a\colon A\to A'$, $b\colon B\to B'$, $c\colon C\to C'$ (Figure~\ref{fig:snake}), so that $b\circ f=f'\circ a$ and $c\circ g=g'\circ b$. There is a homomorphism $\partial\colon\ker c\to\operatorname{coker}a$, the \emph{connecting homomorphism}, such that the sequence
\[\ker a\xrightarrow{f}\ker b\xrightarrow{g}\ker c\xrightarrow{\partial}\operatorname{coker}a\xrightarrow{\bar f'}\operatorname{coker}b\xrightarrow{\bar g'}\operatorname{coker}c\]
is exact, where the first two maps are restrictions of $f,g$ and the last two are induced by $f',g'$. If moreover $f$ is injective, so is $\ker a\to\ker b$; if $g'$ is surjective, so is $\operatorname{coker}b\to\operatorname{coker}c$.
\end{theorem}

\begin{corollary}[short five lemma]\label{cor:fivelemma}
Let a commutative diagram connect two short exact sequences $0\to A\to B\to C\to0$ and $0\to A'\to B'\to C'\to0$ by vertical maps $a,b,c$. If $a$ and $c$ are isomorphisms, so is $b$.
\end{corollary}

\begin{proposition}[Hom is left exact]\label{prop:homleft}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item If $0\to A\xrightarrow fB\xrightarrow gC$ is exact, so is $0\to\operatorname{Hom}(M,A)\xrightarrow{f_*}\operatorname{Hom}(M,B)\xrightarrow{g_*}\operatorname{Hom}(M,C)$.
\item If $A\xrightarrow fB\xrightarrow gC\to0$ is exact, so is $0\to\operatorname{Hom}(C,N)\xrightarrow{g^*}\operatorname{Hom}(B,N)\xrightarrow{f^*}\operatorname{Hom}(A,N)$.
\end{enumerate}
\end{proposition}

\begin{lemma}\label{lem:testexact}
If for every module $N$ the sequence
\[0\to\operatorname{Hom}(C,N)\xrightarrow{g^*}\operatorname{Hom}(B,N)\xrightarrow{f^*}\operatorname{Hom}(A,N)\]
is exact, then $A\xrightarrow fB\xrightarrow gC\to0$ is exact.
\end{lemma}

\begin{definition}\label{def:tensor}
A \emph{tensor product} of $M$ and $N$ is a module $M\otimes_RN$ with a bilinear map $\otimes\colon M\times N\to M\otimes_RN$, $(m,n)\mapsto m\otimes n$, such that for every bilinear $\beta\colon M\times N\to P$ there is exactly one
linear map $\tilde\beta\colon M\otimes_RN\to P$ with $\tilde\beta(m\otimes n)=\beta(m,n)$.
\end{definition}

\begin{theorem}\label{thm:tensorexists}
The tensor product exists, and is unique up to a unique isomorphism compatible with $\otimes$. It is generated by the \emph{pure tensors} $m\otimes n$.
\end{theorem}

\begin{proposition}\label{prop:tensorrules}
There are natural isomorphisms
\begin{enumerate}[label=(\alph*)]
\item $R\otimes M\cong M$, $r\otimes m\mapsto rm$;
\item $M\otimes N\cong N\otimes M$, $m\otimes n\mapsto n\otimes m$;
\item $\bigl(\bigoplus_iM_i\bigr)\otimes N\cong\bigoplus_i(M_i\otimes N)$, $(m_i)_i\otimes n\mapsto(m_i\otimes n)_i$;
\item $(R/I)\otimes M\cong M/IM$ for an ideal $I$, $\bar r\otimes m\mapsto\overline{rm}$, where $IM$ is the submodule generated by the $im$.
\end{enumerate}
\end{proposition}

\begin{example}\label{ex:zmzn}
By (d), $\Z/m\otimes_{\Z}\Z/n\cong(\Z/n)/m(\Z/n)\cong\Z/\gcd(m,n)$, because $m\Z+n\Z=\gcd(m,n)\Z$. With (c) and the structure theorem (Volume~3, Theorem~7.6) this computes the tensor product of any two finitely
generated abelian groups: $\Z^a\oplus\bigoplus_i\Z/m_i$ tensored with $\Z^b\oplus\bigoplus_j\Z/n_j$ is $\Z^{ab}\oplus\bigoplus_i(\Z/m_i)^b\oplus\bigoplus_j(\Z/n_j)^a\oplus\bigoplus_{i,j}\Z/\gcd(m_i,n_j)$. For
vector spaces, if $(e_i)$ and $(f_j)$ are bases of $V$ and $W$, then $(e_i\otimes f_j)$ is a basis of $V\otimes_KW$, by (c) and (a) applied to $V\cong\bigoplus Ke_i$; so $\dim(V\otimes W)=\dim V\dim W$.
\end{example}

\begin{theorem}[tensor and Hom are adjoint]\label{thm:tensorhom}
For modules $M,N,P$ there is an isomorphism, natural in $M$ and $P$,
\[\Phi\colon\operatorname{Hom}(M\otimes N,P)\to\operatorname{Hom}\bigl(M,\operatorname{Hom}(N,P)\bigr),\qquad\Phi(u)(m)=\bigl(n\mapsto u(m\otimes n)\bigr).\]
So $-\otimes N$ is left adjoint to $\operatorname{Hom}(N,-)$.
\end{theorem}

\begin{corollary}[tensor is right exact]\label{cor:rightexact}
If $A\xrightarrow fB\xrightarrow gC\to0$ is exact, so is $A\otimes N\xrightarrow{f\otimes1}B\otimes N\xrightarrow{g\otimes1}C\otimes N\to0$.
\end{corollary}

\begin{definition}\label{def:projective}
A module $P$ is \emph{projective} if $\operatorname{Hom}(P,-)$ preserves short exact sequences; by Proposition~\ref{prop:homleft} this means that for every surjection $g\colon B\to C$, every homomorphism $P\to C$ lifts to $P\to B$.
A module $E$ is \emph{injective} if $\operatorname{Hom}(-,E)$ preserves short exact sequences: for every injection $f\colon A\to B$, every homomorphism $A\to E$ extends to $B\to E$. A module $N$ is \emph{flat} if $-\otimes N$ preserves short
exact sequences: for every injection $f$, $f\otimes1_N$ is injective.
\end{definition}

\begin{proposition}\label{prop:projective}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item Free modules are projective, and a module is projective if and only if it is a direct summand of a free module.
\item Free modules are flat, a direct summand of a flat module is flat, and hence projective modules are flat.
\item Over a domain, a flat module $N$ is \emph{torsion-free}: $rx=0$ with $r\ne0$ implies $x=0$.
\end{enumerate}
\end{proposition}

\begin{theorem}[Baer's criterion]\label{thm:baer}
A module $E$ is injective if and only if every homomorphism $I\to E$, from an ideal $I$ of $R$, extends to $R$.
\end{theorem}

\begin{corollary}\label{cor:divisible}
Over a principal ideal domain, a module $E$ is injective if and only if it is \emph{divisible}: for every $e\in E$ and $r\ne0$ there is $e'$ with $re'=e$. In particular $\Q$ and $\Q/\Z$ are injective abelian groups, and $\Z$ is not.
\end{corollary}

\begin{theorem}\label{thm:pidflat}
For a finitely generated module $M$ over a principal ideal domain, the following are equivalent: $M$ is free; $M$ is projective; $M$ is flat; $M$ is torsion-free.
\end{theorem}

\begin{exercise}[$\star$]\label{ex:zmzncomp}
Show that $\operatorname{Hom}_{\Z}(\Z/m,\Z/n)\cong\Z/\gcd(m,n)$, and that $\Q\otimes_{\Z}\Q/\Z=0$. More generally, show that $D\otimes T=0$ when $D$ is divisible and $T$ is torsion (every element killed by some $n\ne0$).
\end{exercise}

\begin{exercise}[$\star$]\label{ex:whichsplit}
Which of these short exact sequences split? $0\to\Z/2\to\Z/6\to\Z/3\to0$; $0\to\Z/3\to\Z/9\to\Z/3\to0$; $0\to\Z^2\xrightarrow{u}\Z^2\to\Z/5\to0$ with $u(x,y)=(x,5y)$; and $0\to K\to\Z^2\to\Z\to0$ for any surjection $\Z^2\to\Z$ with kernel $K$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:composite}
Let $f\colon A\to B$ and $g\colon B\to C$ be homomorphisms. Show that there is an exact sequence
\[0\to\ker f\to\ker(g\circ f)\to\ker g\to\operatorname{coker}f\to\operatorname{coker}(g\circ f)\to\operatorname{coker}g\to0.\]
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:qnotproj}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item Show that $\operatorname{Hom}_{\Z}(\Q,\Z)=0$, and deduce that $\Q$ is not a projective abelian group.
\item Show that a direct sum of injective modules indexed by a finite set is injective, and that $\Q/\Z\cong\bigoplus_p\Z[1/p]/\Z$, the sum over the primes.
\end{enumerate}
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:tensoralgebra}
If $A,B$ are commutative $R$-algebras, $A\otimes_RB$ is a commutative ring with $(a\otimes b)(a'\otimes b')=aa'\otimes bb'$ (one may take this for granted). Show that $\C\otimes_{\R}\C\cong\C\times\C$ as rings, and that
$\Q(\sqrt2)\otimes_{\Q}\Q(\sqrt3)$ is a field, isomorphic to $\Q(\sqrt2,\sqrt3)$. (Use $R[X]/(p)\otimes_RA\cong A[X]/(p)$.)
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:fivelemma}
\emph{The five lemma.} In a commutative diagram with exact rows $A_1\to A_2\to A_3\to A_4\to A_5$ and $B_1\to\dots\to B_5$, connected by vertical maps $h_1,\dots,h_5$, suppose $h_2,h_4$ are isomorphisms, $h_1$ is surjective and $h_5$ is
injective. Show that $h_3$ is an isomorphism.
\end{exercise}

\begin{proposition}\label{prop:noetherian}
For a ring $R$, the following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item every ideal of $R$ is finitely generated;
\item every increasing chain of ideals $I_1\subseteq I_2\subseteq\cdots$ is eventually constant (the \emph{ascending chain condition});
\item every non-empty set of ideals has a maximal element for inclusion.
\end{enumerate}
A ring with these properties is called \emph{Noetherian}, after Emmy Noether, who made the ascending chain condition the foundation of the theory in 1921. The same equivalences, with the same
proof, hold for the submodules of a module, and define \emph{Noetherian modules}.
\end{proposition}

\begin{proposition}\label{prop:noethmodules}
Let $0\to M'\to M\to M''\to0$ be a short exact sequence of modules. Then $M$ is Noetherian if and only if $M'$ and $M''$ are. Consequently, over a Noetherian ring every finitely generated module is
Noetherian, and so is each of its submodules.
\end{proposition}

\begin{theorem}[Hilbert's basis theorem, 1890]\label{thm:hilbertbasis}
If $R$ is Noetherian, so is $R[X]$. Hence $K[X_1,\dots,X_n]$ and $\Z[X_1,\dots,X_n]$ are Noetherian, for every field $K$, and so is every finitely generated algebra over a Noetherian ring.
\end{theorem}

\begin{corollary}\label{cor:finitesystem}
Every system of polynomial equations $\{f=0:f\in S\}$ in $n$ unknowns, with $S\subseteq K[X_1,\dots,X_n]$ arbitrary, has the same solutions as a finite subsystem.
\end{corollary}

\begin{proposition}[the Zariski topology]\label{prop:zariski}
$V(A)=\varnothing$, $V(0)=K^n$, $V(I)\cup V(J)=V(IJ)$ and $\bigcap_\lambda V(I_\lambda)=V\bigl(\sum_\lambda I_\lambda\bigr)$. Hence the algebraic sets are the closed sets of a topology on $K^n$, the \emph{Zariski topology}. For a closed set $Y$,
$V(I(Y))=Y$.
\end{proposition}

\begin{definition}\label{def:irreducible}
A non-empty topological space $Y$ is \emph{irreducible} if it is not the union of two closed proper subsets; equivalently, any two non-empty open subsets of $Y$ meet. A space is \emph{Noetherian} if every decreasing
sequence of closed subsets is eventually constant.
\end{definition}

\begin{proposition}\label{prop:components}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item $K^n$ with its Zariski topology, and each of its subsets, is a Noetherian space.
\item A closed set $Y\subseteq K^n$ is irreducible if and only if $I(Y)$ is a prime ideal.
\item Every non-empty closed subset of a Noetherian space is a finite union $Y=Y_1\cup\dots\cup Y_r$ of irreducible closed subsets, and this decomposition is unique if one requires $Y_i\not\subseteq Y_j$ for $i\ne j$. The
$Y_i$ are the \emph{irreducible components} of $Y$.
\end{enumerate}
\end{proposition}

\begin{lemma}[Artin and Tate]\label{lem:artintate}
Let $A\subseteq B\subseteq C$ be rings, with $A$ Noetherian, $C$ finitely generated as an $A$-algebra, and $C$ finitely generated as a $B$-module. Then $B$ is finitely generated as an $A$-algebra.
\end{lemma}

\begin{theorem}[Zariski's lemma]\label{thm:zariskilemma}
Let $K$ be a field and $L$ a field that is finitely generated as a $K$-algebra. Then $L$ is a finite extension of $K$.
\end{theorem}

\begin{theorem}[weak Nullstellensatz]\label{thm:weaknull}
Let $K$ be algebraically closed and $I$ a proper ideal of $K[X_1,\dots,X_n]$. Then $V(I)\ne\varnothing$. Moreover the maximal ideals of $K[X_1,\dots,X_n]$ are exactly the ideals $(X_1-a_1,\dots,X_n-a_n)$, for $a\in K^n$.
\end{theorem}

\begin{theorem}[Hilbert's Nullstellensatz, 1893]\label{thm:nullstellensatz}
Let $K$ be algebraically closed and $J$ an ideal of $K[X_1,\dots,X_n]$. Then $I(V(J))=\sqrt J$.
\end{theorem}

\begin{corollary}[the dictionary]\label{cor:dictionary}
Over an algebraically closed field $K$, the maps $V$ and $I$ are inverse, inclusion-reversing bijections between radical ideals of $K[X_1,\dots,X_n]$ and closed subsets of $K^n$. Under them, prime ideals correspond to
irreducible closed sets, and maximal ideals to points.
\end{corollary}

\begin{definition}\label{def:monomialorder}
A \emph{monomial order} is a total order $<$ on the monomials $X^\alpha$ such that $1\le X^\alpha$ for all $\alpha$, and $X^\alpha<X^\beta$ implies $X^{\alpha+\gamma}<X^{\beta+\gamma}$. For a non-zero polynomial $f$, its \emph{leading monomial}
$\operatorname{LM}(f)$ is the largest monomial occurring in it, $\operatorname{LC}(f)$ its coefficient and $\operatorname{LT}(f)=\operatorname{LC}(f)\operatorname{LM}(f)$ its leading term.
\end{definition}

\begin{lemma}[Dickson]\label{lem:dickson}
A monomial ideal generated by a set $M$ of monomials is generated by a finite subset of $M$. Consequently a monomial order is a well-order: every non-empty set of monomials has a least element.
\end{lemma}

\begin{proposition}[division]\label{prop:division}
Fix a monomial order and non-zero $g_1,\dots,g_k$. Every $f$ can be written $f=\sum_iq_ig_i+r$, where no monomial of $r$ is divisible by any $\operatorname{LM}(g_i)$, and where $\operatorname{LM}(q_ig_i)\le\operatorname{LM}(f)$ whenever $q_ig_i\ne0$.
\end{proposition}

\begin{definition}\label{def:groebner}
Let $I$ be a non-zero ideal. A finite set $G=\{g_1,\dots,g_k\}\subseteq I$ is a \emph{Gröbner basis} of $I$ if the leading monomials of $G$ generate the monomial ideal $(\operatorname{LM}(I))$ generated by all leading monomials of
elements of $I$.
\end{definition}

\begin{proposition}\label{prop:groebnerprops}
Every non-zero ideal has a Gröbner basis. If $G$ is a Gröbner basis of $I$, then $G$ generates $I$, the remainder of $f$ on division by $G$ does not depend on the choices made, and $f\in I$ if and only if this remainder is $0$.
\end{proposition}

\begin{lemma}\label{lem:cancel}
Let $p=\sum_jc_jX^{\beta_j}g_{i_j}$, a finite sum with $c_j\in K$, in which every term $X^{\beta_j}g_{i_j}$ has the same leading monomial $X^\delta$, and suppose $\operatorname{LM}(p)<X^\delta$ (or $p=0$). Then $p$ is a linear
combination, with coefficients in $K$, of polynomials $X^{\delta-\gamma}S(g_{i_j},g_{i_l})$, where $X^\gamma$ is the lcm of the leading monomials of $g_{i_j}$ and $g_{i_l}$, each with leading monomial less than $X^\delta$.
\end{lemma}

\begin{theorem}[Buchberger's criterion, 1965]\label{thm:buchberger}
A finite set $G=\{g_1,\dots,g_k\}$ of non-zero polynomials is a Gröbner basis of the ideal it generates if and only if, for all $i<j$, the remainder of $S(g_i,g_j)$ on division by $G$ is $0$.
\end{theorem}

\begin{corollary}[Buchberger's algorithm]\label{cor:buchalg}
Start from generators $G$ of $I$. As long as some $S(g_i,g_j)$ has a non-zero remainder $r$ on division by $G$, add $r$ to $G$. This process stops, and then $G$ is a Gröbner basis of $I$.
\end{corollary}

\begin{exercise}[$\star$]\label{ex:nonnoeth}
Show that the subring $K[X,XY,XY^2,XY^3,\dots]$ of the Noetherian ring $K[X,Y]$ is not Noetherian.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:radicals}
Over $\C$, find the irreducible components of $V(X^2-Y^2)$ and of $V(XY,XZ,YZ)\subseteq\C^3$, and compute $I(V(X^2Y,XY^2))$ in $\C[X,Y]$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:notproduct}
Let $K$ be infinite. Show that the diagonal $\{(x,x)\}$ is closed in the Zariski topology of $K^2$, but not in the product of the Zariski topologies of $K$ and $K$. Deduce that the Zariski topology of $K^2$ is strictly finer
than the product topology.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:realnull}
Over $\R$: show that every algebraic subset of $\R^n$ is the zero set of a single polynomial, and that the Nullstellensatz fails. Which ideal $J$ of $\R[X,Y]$ has $I(V(J))\ne\sqrt J$ with $V(J)$ a single point?
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:colouring}
Let $\Gamma$ be a finite graph with vertex set $\{1,\dots,n\}$, and $\omega=e^{2\pi i/3}$. Show that $\Gamma$ can be properly coloured with three colours if and only if the polynomials $X_v^3-1$ ($v$ a vertex) and
$X_u^2+X_uX_v+X_v^2$ ($uv$ an edge) have a common zero in $\C^n$, if and only if they do not generate the unit ideal of $\C[X_1,\dots,X_n]$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:groebnerhand}
Compute by hand, with Buchberger's algorithm, a Gröbner basis of $I=(X^2-Y,\,X^3-X)$ in $\C[X,Y]$ for the lexicographic order with $X>Y$, and use it to find $V(I)$. Is $I$ radical?
\end{exercise}

\begin{definition}\label{def:localisation}
For a multiplicative $S$, the \emph{ring of fractions} $S^{-1}R$ is the set of pairs $(r,s)\in R\times S$ modulo the relation $(r,s)\sim(r',s')$ if $t(rs'-r's)=0$ for some $t\in S$, with the class of $(r,s)$ written $r/s$ and
the operations $\frac rs+\frac{r'}{s'}=\frac{rs'+r's}{ss'}$, $\frac rs\cdot\frac{r'}{s'}=\frac{rr'}{ss'}$. The map $\iota\colon R\to S^{-1}R$, $r\mapsto r/1$, is a ring homomorphism. For $S=\{f^n\}$ one writes $R_f$, and for $S=R\setminus\mathfrak p$, $R_{\mathfrak p}$,
the \emph{localisation of $R$ at $\mathfrak p$}. For a module $M$, $S^{-1}M$ is defined in the same way, with $m/s$ for $m\in M$.
\end{definition}

\begin{proposition}[universal property]\label{prop:locuniv}
$\iota(s)$ is a unit of $S^{-1}R$ for every $s\in S$, and every ring homomorphism $\varphi\colon R\to T$ such that $\varphi(s)$ is a unit for every $s\in S$ factors uniquely as $\varphi=\bar\varphi\circ\iota$. Moreover
$\iota(r)=0$ if and only if $sr=0$ for some $s\in S$.
\end{proposition}

\begin{proposition}[localisation is exact]\label{prop:locexact}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item There is a natural isomorphism $S^{-1}R\otimes_RM\cong S^{-1}M$, $\frac rs\otimes m\mapsto\frac{rm}s$.
\item If $M'\xrightarrow fM\xrightarrow gM''$ is exact, so is $S^{-1}M'\to S^{-1}M\to S^{-1}M''$, with the maps $m/s\mapsto f(m)/s$ and $m/s\mapsto g(m)/s$.
\item Hence $S^{-1}R$ is a flat $R$-module. In particular $\Q$ is a flat $\Z$-module.
\end{enumerate}
\end{proposition}

\begin{theorem}[primes of a ring of fractions]\label{thm:locprimes}
The maps $\mathfrak p\mapsto S^{-1}\mathfrak p=\{p/s:p\in\mathfrak p,s\in S\}$ and $\mathfrak q\mapsto\iota^{-1}(\mathfrak q)$ are inverse, inclusion-preserving bijections between the prime ideals of $R$ that do not meet $S$ and the prime
ideals of $S^{-1}R$.
\end{theorem}

\begin{corollary}\label{cor:localring}
For a prime $\mathfrak p$, the ring $R_{\mathfrak p}$ has exactly one maximal ideal, $\mathfrak pR_{\mathfrak p}$, and its primes correspond to the primes of $R$ contained in $\mathfrak p$.
\end{corollary}

\begin{theorem}[Nakayama's lemma]\label{thm:nakayama}
Let $(R,\mathfrak m)$ be a local ring and $M$ a finitely generated $R$-module with $\mathfrak mM=M$. Then $M=0$.
\end{theorem}

\begin{corollary}\label{cor:mingens}
Let $(R,\mathfrak m)$ be local with residue field $k$ and $M$ finitely generated. Elements $m_1,\dots,m_n\in M$ generate $M$ if and only if their images span the $k$-vector space $M/\mathfrak mM$. So every minimal generating family of
$M$ has $\dim_kM/\mathfrak mM$ elements.
\end{corollary}

\begin{proposition}\label{prop:localzero}
For a module $M$, the following are equivalent: $M=0$; $M_{\mathfrak p}=0$ for every prime $\mathfrak p$; $M_{\mathfrak m}=0$ for every maximal ideal $\mathfrak m$. Consequently a homomorphism is injective, or surjective, if and only if
it is so after localisation at every maximal ideal.
\end{proposition}

\begin{definition}\label{def:spec}
The \emph{spectrum} $\operatorname{Spec}R$ is the set of prime ideals of $R$. For an ideal $I$, let $V(I)=\{\mathfrak p:\mathfrak p\supseteq I\}$. These sets are the closed sets of a topology, the \emph{Zariski topology} of $\operatorname{Spec}R$. A ring
homomorphism $\varphi\colon R\to T$ induces the map $\operatorname{Spec}T\to\operatorname{Spec}R$, $\mathfrak q\mapsto\varphi^{-1}(\mathfrak q)$, which is continuous.
\end{definition}

\begin{theorem}[the primes of $\Z\lbrack x\rbrack$]\label{thm:speczx}
The prime ideals of $\Z[x]$ are:
\begin{enumerate}[label=(\alph*)]
\item $(0)$;
\item the principal ideals $(f)$, for $f$ irreducible in $\Z[x]$: a prime number $p$, or a primitive polynomial irreducible over $\Q$;
\item the maximal ideals $(p,f)$, for $p$ prime and $f\in\Z[x]$ whose reduction modulo $p$ is irreducible in $\mathbb F_p[x]$.
\end{enumerate}
\end{theorem}

\begin{definition}\label{def:integral}
Let $A\subseteq B$ be rings. An element $b\in B$ is \emph{integral} over $A$ if it is a root of a monic polynomial with coefficients in $A$. The ring $B$ is \emph{integral} over $A$ if all its elements are.
\end{definition}

\begin{proposition}\label{prop:integralcrit}
For $b\in B$, the following are equivalent: (a) $b$ is integral over $A$; (b) $A[b]$ is a finitely generated $A$-module; (c) $b$ lies in a subring $C\subseteq B$ containing $A$ that is a finitely generated $A$-module.
\end{proposition}

\begin{corollary}\label{cor:integralclosure}
The elements of $B$ integral over $A$ form a subring, the \emph{integral closure} of $A$ in $B$. If $C$ is integral over $B$ and $B$ integral over $A$, then $C$ is integral over $A$.
\end{corollary}

\begin{lemma}\label{lem:intfield}
Let $A\subseteq B$ be domains, with $B$ integral over $A$. Then $B$ is a field if and only if $A$ is a field. Moreover every non-zero ideal of $B$ meets $A$ in a non-zero ideal.
\end{lemma}

\begin{theorem}[Cohen and Seidenberg, 1946]\label{thm:goingup}
Let $B$ be integral over $A\subseteq B$.
\begin{enumerate}[label=(\alph*)]
\item (\emph{Incomparability}) If $\mathfrak q\subseteq\mathfrak q'$ are primes of $B$ with $\mathfrak q\cap A=\mathfrak q'\cap A$, then $\mathfrak q=\mathfrak q'$.
\item (\emph{Lying over}) For every prime $\mathfrak p$ of $A$ there is a prime $\mathfrak q$ of $B$ with $\mathfrak q\cap A=\mathfrak p$.
\item (\emph{Going up}) If $\mathfrak p\subseteq\mathfrak p'$ are primes of $A$ and $\mathfrak q\cap A=\mathfrak p$, there is a prime $\mathfrak q'\supseteq\mathfrak q$ with $\mathfrak q'\cap A=\mathfrak p'$.
\end{enumerate}
\end{theorem}

\begin{definition}\label{def:krulldim}
The \emph{Krull dimension} $\dim R$ is the supremum of the lengths $m$ of chains of prime ideals $\mathfrak p_0\subsetneq\mathfrak p_1\subsetneq\dots\subsetneq\mathfrak p_m$.
\end{definition}

\begin{corollary}\label{cor:dimintegral}
If $B$ is integral over $A\subseteq B$, then $\dim B=\dim A$.
\end{corollary}

\begin{lemma}[Noether's change of variables]\label{lem:noethervar}
Let $K$ be a field and $f\in K[x_1,\dots,x_n]$ non-constant, $n\ge1$. For a large enough integer $r$, after the substitution $x_i=y_i+x_n^{r^i}$ for $i<n$, the polynomial $f$ becomes $c\,x_n^N+(\text{terms of lower degree in }x_n)$, with $c\in K$
non-zero and coefficients in $K[y_1,\dots,y_{n-1}]$.
\end{lemma}

\begin{theorem}[Noether normalisation, 1926]\label{thm:noethernorm}
Let $A$ be a finitely generated algebra over a field $K$. There are elements $z_1,\dots,z_d\in A$, algebraically independent over $K$, such that $A$ is integral over $K[z_1,\dots,z_d]$.
\end{theorem}

\begin{theorem}\label{thm:dimpoly}
For every field $K$, the polynomial ring $K[x_1,\dots,x_n]$ has dimension $n$. Consequently, if a finitely generated $K$-algebra $A$ is integral over $K[z_1,\dots,z_d]$ with the $z_i$ algebraically independent, then $\dim A=d$.
\end{theorem}

\begin{definition}\label{def:primary}
A proper ideal $\mathfrak q$ of a ring $R$ is \emph{primary} if $ab\in\mathfrak q$ and $a\notin\mathfrak q$ imply $b^n\in\mathfrak q$ for some $n\ge1$.
\end{definition}

\begin{lemma}\label{lem:primaryradical}
Let $\mathfrak q$ be primary and set $\mathfrak p=\sqrt{\mathfrak q}$. Then $\mathfrak p$ is prime. One says that $\mathfrak q$ is $\mathfrak p$-primary.
\end{lemma}

\begin{lemma}\label{lem:irredprimary}
Let $R$ be Noetherian and let $I$ be a proper ideal that is not the intersection of two strictly larger ideals. Then $I$ is primary.
\end{lemma}

\begin{theorem}[Lasker--Noether]\label{thm:laskernoether}
Every proper ideal of a Noetherian ring is a finite intersection of primary ideals.
\end{theorem}

\begin{theorem}\label{thm:assprimes}
Let $I=\mathfrak q_1\cap\cdots\cap\mathfrak q_r$ be a minimal primary decomposition in a Noetherian ring, with $\mathfrak p_i=\sqrt{\mathfrak q_i}$. A prime ideal is equal to $\sqrt{(I:x)}$ for some $x\in R$ if and only if it equals some $\mathfrak p_i$. These primes, the \emph{associated primes} of $I$, are therefore independent of the chosen minimal decomposition. The minimal members of the set are exactly the prime ideals minimal among those containing $I$. Any other associated prime contains one of these and is called \emph{embedded}.
\end{theorem}

\begin{exercise}[$\star$]\label{ex:subringsq}
Show that every subring of $\Q$ is a ring of fractions $S^{-1}\Z$, and that the ideals of $\Z_{(p)}$ are $0$ and the $p^k\Z_{(p)}$. What is $\operatorname{Spec}\Z_{(p)}$?
\end{exercise}

\begin{exercise}[$\star$]\label{ex:golden}
Show that $\Z[\sqrt5]$ is not integrally closed, and that $\Z[\frac{1+\sqrt5}2]$ is a finitely generated $\Z$-module. Find a monic equation over $\Z$ for $\sqrt2+\sqrt3$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:localiff}
Show that a ring is local if and only if its non-units form an ideal. Show that $R_f=0$ if and only if $f$ is nilpotent, and that the nilpotent elements of $R$ form the intersection of all its prime ideals.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:specrx}
Describe $\operatorname{Spec}\R[x]$, and show that its closed points are in bijection with the upper half-plane $\{z\in\C:\operatorname{Im}z\ge0\}$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:quasicompact}
Show that $\operatorname{Spec}R$ is quasi-compact: every cover by open sets has a finite subcover. (The open sets $D(f)=\operatorname{Spec}R\setminus V(f)$ form a basis.)
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:hyperbola}
Let $A=\C[x,y]/(xy-1)$. Show that $A$ is not integral over $\C[x]$, but is integral over $\C[x+y]$. Interpret geometrically, with the projections of the hyperbola $xy=1$ to the two axes.
\end{exercise}

\begin{lemma}\label{lem:invertible}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item If $IJ=R$, then $J=(R:I)$, and $I$ is finitely generated. One writes $I^{-1}=(R:I)$.
\item A product $IJ$ is invertible if and only if $I$ and $J$ are.
\item If $R$ is local, a fractional ideal is invertible if and only if it is principal.
\item If $I$ is finitely generated, then $I$ is invertible if and only if $I_{\mathfrak m}$ is invertible in $R_{\mathfrak m}$ for every maximal ideal $\mathfrak m$.
\end{enumerate}
\end{lemma}

\begin{definition}\label{def:dvr}
A \emph{discrete valuation ring} (DVR) is a principal ideal domain with exactly one non-zero prime ideal.
\end{definition}

\begin{theorem}\label{thm:dvr}
Let $(R,\mathfrak m)$ be a Noetherian local domain whose only non-zero prime ideal is $\mathfrak m\ne0$. The following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item $R$ is a discrete valuation ring;
\item $R$ is integrally closed;
\item $\mathfrak m$ is principal;
\item $\mathfrak m$ is invertible.
\end{enumerate}
Moreover (c) implies (a) for every Noetherian local domain with $\mathfrak m\ne0$.
\end{theorem}

\begin{definition}\label{def:dedekind}
A \emph{Dedekind domain} is a Noetherian, integrally closed domain, not a field, in which every non-zero prime ideal is maximal.
\end{definition}

\begin{theorem}[Noether, 1927]\label{thm:dedekind}
For a Noetherian domain $R$ that is not a field, the following are equivalent:
\begin{enumerate}[label=(\alph*)]
\item $R$ is a Dedekind domain;
\item $R_{\mathfrak p}$ is a discrete valuation ring for every non-zero prime $\mathfrak p$;
\item every fractional ideal of $R$ is invertible;
\item every non-zero proper ideal of $R$ is a product of prime ideals.
\end{enumerate}
In that case the factorisation in (d) is unique up to the order of the factors.
\end{theorem}

\begin{corollary}[to contain is to divide]\label{cor:contain}
Let $R$ be Dedekind and $I,J$ fractional ideals. Then $J\subseteq I$ if and only if $J=IL$ for an ideal $L\subseteq R$, if and only if $v_{\mathfrak p}(J)\ge v_{\mathfrak p}(I)$ for every $\mathfrak p$. Consequently
\[
v_{\mathfrak p}(I+J)=\min\bigl(v_{\mathfrak p}(I),v_{\mathfrak p}(J)\bigr),\qquad v_{\mathfrak p}(I\cap J)=\max\bigl(v_{\mathfrak p}(I),v_{\mathfrak p}(J)\bigr).
\]
\end{corollary}

\begin{definition}\label{def:classgroup}
For a Dedekind domain $R$, the \emph{class group} $\operatorname{Cl}(R)$ is the quotient of $\mathcal I(R)$ by the subgroup $\mathcal P(R)$ of principal fractional ideals. Its order, when finite, is the \emph{class number}.
\end{definition}

\begin{proposition}[one and a half generators]\label{prop:twogen}
Let $R$ be Dedekind, $I$ a non-zero ideal and $0\ne a\in I$. Then $I=(a,b)$ for some $b\in I$.
\end{proposition}

\begin{lemma}\label{lem:trace}
Let $L/K$ be a finite extension of degree $n$ and $y\in L$, with minimal polynomial $f$ of degree $d$ over $K$. The characteristic polynomial $\chi_y$ of the $K$-linear map $m_y\colon L\to L$, $z\mapsto yz$, is $f^{n/d}$. Its trace
is the \emph{trace} $\operatorname{Tr}_{L/K}(y)$. If $R$ is integrally closed with fraction field $K$ and $y$ is integral over $R$, then $\chi_y\in R[x]$ and $\operatorname{Tr}_{L/K}(y)\in R$.
\end{lemma}

\begin{theorem}\label{thm:intclosure}
Let $R$ be a Dedekind domain with fraction field $K$, $L/K$ a finite separable extension of degree $n$, and $S$ the integral closure of $R$ in $L$. Then:
\begin{enumerate}[label=(\alph*)]
\item there is $\theta\in S$ with $L=K(\theta)$, and $dS\subseteq R[\theta]$ where $d=\det\bigl(\operatorname{Tr}_{L/K}(\theta^{i+j})\bigr)_{0\le i,j<n}$ is non-zero;
\item $S$ is a finitely generated $R$-module, and a Dedekind domain with fraction field $L$.
\end{enumerate}
\end{theorem}

\begin{theorem}[the fundamental identity]\label{thm:fundid}
$\displaystyle\sum_{i=1}^ge_if_i=n$.
\end{theorem}

\begin{exercise}[$\star$]\label{ex:zsqrt5}
In $R=\Z[\sqrt{-5}]$, with the norm $N(a+b\sqrt{-5})=a^2+5b^2$, prove the four factorisations of Example~\ref{ex:sixtwice}, and show that $\mathfrak p=(2,1+\sqrt{-5})$ is not principal.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:powerseries}
Let $k$ be a field. Show that $k[[t]]$, the ring of formal power series, is a DVR, and describe its valuation.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:semilocal}
Show that a Dedekind domain with only finitely many prime ideals is a principal ideal domain.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:notdedekind}
Show that $\C[x,y]$ and $\Z[\sqrt{-3}]$ are Noetherian domains that are not Dedekind, and in each case find a non-zero prime ideal that is not invertible.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:circle}
Let $A=\R[x,y]/(x^2+y^2-1)$, a Dedekind domain (take this for granted). Show that $\mathfrak m=(x-1,y)$ is not principal but $\mathfrak m^2=(x-1)$, and that $A\otimes_\R\C\cong\C[u,u^{-1}]$ is a principal ideal domain.
(One can show that $\operatorname{Cl}(A)\cong\Z/2$; this is not proved here.)
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:cubicnotprincipal}
Let $A=\C[x,y]/(y^2-x^3+x)$, and $N(a+by)=a^2-b^2(x^3-x)\in\C[x]$ for $a,b\in\C[x]$.
\begin{enumerate}[label=(\alph*)]
\item Show that every element of $A$ is uniquely $a+by$ with $a,b\in\C[x]$, that $N$ is multiplicative, and that the units of $A$ are the non-zero constants.
\item Show that $\mathfrak m=(x,y)$ satisfies $\mathfrak m^2=(x)$, and that it is not principal. (Look at the degree of $N$.)
\item Show that $A$ is integrally closed.
\end{enumerate}
\end{exercise}

\begin{theorem}[comparison theorem]\label{thm:comparison}
Let $P_\bullet\to M$ be a projective resolution, $Q_\bullet\to N$ an exact sequence $\cdots\to Q_1\to Q_0\to N\to0$ (not necessarily projective), and $f\colon M\to N$ a homomorphism. There is a chain map $f_\bullet\colon P_\bullet\to Q_\bullet$
with $\varepsilon_Q\circ f_0=f\circ\varepsilon_P$, and any two such chain maps are chain homotopic.
\end{theorem}

\begin{lemma}[horseshoe lemma]\label{lem:horseshoe}
Let $0\to A\xrightarrow iB\xrightarrow pC\to0$ be exact, and $P'_\bullet\to A$, $P''_\bullet\to C$ projective resolutions. Then $B$ has a projective resolution $P_\bullet$ with $P_n=P'_n\oplus P''_n$, such that the inclusions and projections
form a short exact sequence of complexes $0\to P'_\bullet\to P_\bullet\to P''_\bullet\to0$, compatible with $i$ and $p$.
\end{lemma}

\begin{proposition}\label{prop:torextbasic}
\leavevmode
\begin{enumerate}[label=(\alph*)]
\item Up to canonical isomorphism, $\operatorname{Tor}_n(M,N)$ and $\operatorname{Ext}^n(M,N)$ do not depend on the resolution, and they are functors of $M$ and of $N$.
\item $\operatorname{Tor}_0(M,N)\cong M\otimes N$ and $\operatorname{Ext}^0(M,N)\cong\operatorname{Hom}(M,N)$.
\item If $M$ is projective, then $\operatorname{Tor}_n(M,N)$ and $\operatorname{Ext}^n(M,N)$ vanish for $n\ge1$. If $N$ is flat, $\operatorname{Tor}_n(M,N)=0$ for $n\ge1$; if $N$ is injective, $\operatorname{Ext}^n(M,N)=0$ for $n\ge1$.
\end{enumerate}
\end{proposition}

\begin{theorem}[long exact sequences]\label{thm:les}
A short exact sequence $0\to A\to B\to C\to0$ gives long exact sequences
\[
\begin{gathered}
\cdots\to\operatorname{Tor}_1(A,N)\to\operatorname{Tor}_1(B,N)\to\operatorname{Tor}_1(C,N)\to A\otimes N\to B\otimes N\to C\otimes N\to0,\\
\cdots\to\operatorname{Tor}_1(M,C)\to M\otimes A\to M\otimes B\to M\otimes C\to0,\\
0\to\operatorname{Hom}(C,N)\to\operatorname{Hom}(B,N)\to\operatorname{Hom}(A,N)\to\operatorname{Ext}^1(C,N)\to\operatorname{Ext}^1(B,N)\to\cdots,\\
0\to\operatorname{Hom}(M,A)\to\operatorname{Hom}(M,B)\to\operatorname{Hom}(M,C)\to\operatorname{Ext}^1(M,A)\to\operatorname{Ext}^1(M,B)\to\cdots,
\end{gathered}
\]
with $\operatorname{Tor}_{n+1}(\cdot,\cdot)\to\operatorname{Tor}_n(\cdot,\cdot)$ and $\operatorname{Ext}^n\to\operatorname{Ext}^{n+1}$ continuing each sequence in the same pattern.
\end{theorem}

\begin{corollary}\label{cor:torflat}
A module $N$ is flat if and only if $\operatorname{Tor}_1(M,N)=0$ for every module $M$.
\end{corollary}

\begin{proposition}\label{prop:pidvanish}
Over a principal ideal domain, $\operatorname{Tor}_n(M,N)=\operatorname{Ext}^n(M,N)=0$ for $n\ge2$ and all finitely generated $M$.
\end{proposition}

\begin{theorem}\label{thm:extclass}
There is a bijection between $\operatorname{Ext}^1(M,N)$ and the set of equivalence classes of extensions of $M$ by $N$, which sends $0$ to the class of the split extension.
\end{theorem}

\begin{example}\label{ex:extzp}
$\operatorname{Ext}^1(\Z/p,\Z/p)\cong\Z/p$ has $p$ elements, so there are exactly $p$ classes of extensions $0\to\Z/p\to E\to\Z/p\to0$. One is $E=(\Z/p)^2$. The other $p-1$ all have $E\cong\Z/p^2$, but they are not
equivalent to each other: for $a=1,\dots,p-1$, take $j(n)=pn$ and $q(x)=ax\bmod p$ (Exercise~\ref{ex:extzp2}). Equivalence of extensions remembers the maps, not only the middle group.
\end{example}

\begin{theorem}[universal coefficient theorems]\label{thm:uct}
Let $R$ be a principal ideal domain, $C_\bullet$ a chain complex of finitely generated free $R$-modules, and $A$ a module. For every $n$ there are exact sequences
\[
\begin{gathered}
0\to H_n(C)\otimes A\to H_n(C\otimes A)\to\operatorname{Tor}_1\bigl(H_{n-1}(C),A\bigr)\to0,\\
0\to\operatorname{Ext}^1\bigl(H_{n-1}(C),A\bigr)\to H^n\bigl(\operatorname{Hom}(C,A)\bigr)\to\operatorname{Hom}\bigl(H_n(C),A\bigr)\to0,
\end{gathered}
\]
natural in $C$ and $A$, and both split (not naturally).
\end{theorem}

\begin{exercise}[$\star$]\label{ex:kleinuct}
The Klein bottle has the complex $\Z\xrightarrow{d_2}\Z^2\xrightarrow{0}\Z$ with $d_2(1)=(0,2)$ (Figure~\ref{fig:surfaces}). Compute its homology with coefficients $\Z$, $\Z/2$ and $\Q$, and its cohomology with coefficients
$\Z$, directly and with Theorem~\ref{thm:uct}.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:torsym}
Show that $\operatorname{Tor}_1(M,N)\cong\operatorname{Tor}_1(N,M)$ for finitely generated abelian groups, and that this group is finite. Is $\operatorname{Ext}^1(\Z/2,\Z)\cong\operatorname{Ext}^1(\Z,\Z/2)$?
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:koszul}
Let $R=K[x,y]$ and $K=R/(x,y)$. Use the Koszul resolution to compute $\operatorname{Tor}_n^R(K,K)$ and $\operatorname{Ext}^n_R(K,R)$ for all $n$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:extzp2}
Prove the claims of Example~\ref{ex:extzp}: for $a\in\{1,\dots,p-1\}$, the extension $E_a$ with $j(n)=pn$ and $q(x)=ax\bmod p$ corresponds to the class $a^{-1}\bmod p$ under the identification $\operatorname{Ext}^1(\Z/p,\Z/p)\cong\Z/p$ of Example~\ref{ex:torextz}, and $E_a$, $E_b$ are equivalent only if $a=b$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:baersum}
(Baer sum.) Given extensions $0\to N\to E_i\to M\to0$ ($i=1,2$), let $X=\{(e_1,e_2):q_1(e_1)=q_2(e_2)\}$ and $E=X/\{(j_1(n),-j_2(n))\}$. Show that $E$ is an extension of $M$ by $N$, and that, with the notation of the proof of
Theorem~\ref{thm:extclass}, $\Theta(E)=\Theta(E_1)+\Theta(E_2)$.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:extqz}
Show that $\operatorname{Ext}^1(\Q,\Z)\cong\operatorname{Hom}(\Q,\Q/\Z)/\Q$, and that $\operatorname{Hom}(\Q,\Q/\Z)$ is uncountable. Deduce that there is an abelian group $E$ containing $\Z$ with $E/\Z\cong\Q$ but $E\not\cong\Z\oplus\Q$.
\end{exercise}

\begin{definition}\label{def:cochains}
The \emph{$n$-cochains} are the functions $f\colon G^n\to A$ (for $n=0$, the elements of $A$). The \emph{coboundaries} $d\colon C^n\to C^{n+1}$ are, for $n=0,1,2$,
\[
\begin{gathered}
(da)(g)=g\cdot a-a,\qquad(df)(g,h)=g\cdot f(h)-f(gh)+f(g),\\
(df)(g,h,k)=g\cdot f(h,k)-f(gh,k)+f(g,hk)-f(g,h).
\end{gathered}
\]
A direct computation, which the reader should do once, gives $d\circ d=0$. Write $Z^n=\ker d$ (\emph{cocycles}), $B^n=\operatorname{im}d$ (\emph{coboundaries}), and $H^n(G,A)=Z^n/B^n$, with $B^0=0$.
\end{definition}

\begin{lemma}\label{lem:normalised}
Every $2$-cocycle is cohomologous to a normalised one.
\end{lemma}

\begin{proposition}\label{prop:complements}
The complements of $A$ in $A\rtimes G$ are the subgroups $K_f=\{(f(g),g):g\in G\}$ for $f\in Z^1(G,A)$, and $K_f,K_{f'}$ are conjugate by an element of $A$ if and only if $f-f'\in B^1$. So $H^1(G,A)$ is in bijection with the
$A$-conjugacy classes of complements.
\end{proposition}

\begin{theorem}[Hilbert, Noether, Speiser]\label{thm:hilbert90}
Let $L/K$ be a finite Galois extension with group $G$. Then $H^1(G,L^\times)=1$ and $H^1(G,L)=0$.
\end{theorem}

\begin{corollary}[Theorem~90 of the \emph{Zahlbericht}]\label{cor:hilbert90}
If $L/K$ is cyclic with generator $\sigma$ and $N(x)=x\,\sigma(x)\cdots\sigma^{n-1}(x)=1$, then $x=b/\sigma(b)$ for some $b\in L^\times$. If $\operatorname{Tr}(x)=0$, then $x=b-\sigma(b)$ for some $b\in L$.
\end{corollary}

\begin{theorem}[Schreier]\label{thm:h2ext}
Let $A$ be a $G$-module. The equivalence classes of extensions of $G$ by $A$ inducing the given action are in bijection with $H^2(G,A)$. The class $0$ corresponds to the semidirect product $A\rtimes G$.
\end{theorem}

\begin{theorem}\label{thm:h2cyclic}
For $G$ cyclic of order $n$ and any $G$-module $A$, $H^2(G,A)\cong A^G/N(A)$. The class of $a\in A^G$ is represented by the cocycle
\[
f_a(\sigma^i,\sigma^j)=\begin{cases}a&\text{if }i+j\ge n,\\0&\text{if }i+j<n,\end{cases}\qquad0\le i,j<n.
\]
\end{theorem}

\begin{example}[carrying]\label{ex:carry}
Let $A=\Z/b$ with trivial action of $G=\Z/b$ (written additively, with generator $1$ and $\sigma^i=i$). Then $A^G=\Z/b$ and $N(x)=bx=0$, so $H^2(\Z/b,\Z/b)\cong\Z/b$. The cocycle $f_1(x,y)=1$ if $x+y\ge b$, $0$ otherwise, for digits
$0\le x,y<b$, is the carry of base-$b$ addition, and the extension it defines is $\Z/b^2$, with $(a,x)$ standing for the number $ab+x$. It generates $H^2$, and its multiples $f_a$, $a\in\Z/b$, give the $b$ classes. For $a=0$ the
extension is $\Z/b\times\Z/b$. In general $t=(0,1)$ has $t^b=(a,0)$, so $t$ has order $b$ times the order of $a$, and $E_{f_a}\cong\Z/b^2$ exactly when $a$ is a unit modulo $b$: there are $\varphi(b)$ inequivalent extensions with
middle group $\Z/b^2$, as in Example~\ref{ex:extzp}. For $b=10$ the other classes give $\Z/20\times\Z/5$ and $\Z/50\times\Z/2$ (Exercise~\ref{ex:carry10}).
\end{example}

\begin{proposition}\label{prop:killed}
Let $G$ be finite of order $m$. Then $m\cdot H^n(G,A)=0$ for $n=1,2$. If moreover $A$ is finite of order prime to $m$, then $H^1(G,A)=H^2(G,A)=0$.
\end{proposition}

\begin{theorem}[Schur, 1904; Zassenhaus, 1937]\label{thm:sz}
Let $E$ be a finite group and $A$ an abelian normal subgroup with $|A|$ prime to $|E/A|$. Then $A$ has a complement in $E$, and any two complements are conjugate.
\end{theorem}

\begin{exercise}[$\star$]\label{ex:h1sign}
Let $G=\Z/2=\{1,\sigma\}$ act on $\Z$ by $\sigma\cdot a=-a$. Compute $H^0$, $H^1$ and $H^2$ (the latter with Theorem~\ref{thm:h2cyclic}), and do the same for the trivial action.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:carry10}
In the setting of Example~\ref{ex:carry} with $b=10$, show that the extension with ``carry $a$'' is isomorphic, as a group, to $\Z/100$ when $\gcd(a,10)=1$, to $\Z/20\times\Z/5$ when $a=5$, to $\Z/50\times\Z/2$ when $a\in\{2,4,6,8\}$, and to
$(\Z/10)^2$ when $a=0$. How many inequivalent extensions have middle group $\Z/100$?
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:quaternion}
The quaternion group $Q_8=\{\pm1,\pm i,\pm j,\pm k\}$ is a central extension of $G=\{1,\bar i,\bar j,\bar k\}\cong(\Z/2)^2$ by $A=\{\pm1\}\cong\Z/2$. Compute its cocycle for the section $\bar g\mapsto g$ ($g\in\{1,i,j,k\}$), and show that it
is not a coboundary in two ways: directly, and by finding the complements.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:cyclich1}
For $G=\langle\sigma\rangle$ cyclic of order $n$, show that $H^1(G,A)\cong\ker N/(\sigma-1)A$. Deduce Corollary~\ref{cor:hilbert90} again from Theorem~\ref{thm:hilbert90}, and conversely.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:artinschreier}
(Artin--Schreier.) Let $K$ have characteristic $p$ and $L/K$ be cyclic of degree $p$ with generator $\sigma$. Show that there is $\alpha\in L$ with $\sigma(\alpha)=\alpha+1$, and that $\alpha$ is a root of $x^p-x-a$ with $a=\alpha^p-\alpha\in K$.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:order20}
Use Theorem~\ref{thm:sz} to show that every group of order $20$ is a semidirect product $\Z/5\rtimes Q$ with $|Q|=4$, and that there are exactly five groups of order $20$ up to isomorphism.
\end{exercise}

\begin{definition}\label{def:semisimple}
A module $M$ over a ring $A$ is \emph{simple} if $M\ne0$ and its only submodules are $0$ and $M$, and \emph{semisimple} if it is a direct sum of simple modules. A ring $A$ is \emph{semisimple} if $A$, as a left module over itself,
is semisimple.
\end{definition}

\begin{lemma}\label{lem:endA}
For any ring $A$, the map $A^{\mathrm{op}}\to\operatorname{End}_A(A)$, $a\mapsto(x\mapsto xa)$, is an isomorphism of rings, where $A^{\mathrm{op}}$ is $A$ with the product reversed.
\end{lemma}

\begin{theorem}[Wedderburn, 1908]\label{thm:wedderburn}
A semisimple ring $A$ whose module $A$ is a finite direct sum of simple modules is isomorphic to a product $M_{n_1}(D_1)\times\dots\times M_{n_r}(D_r)$ of matrix rings over division rings. If $A$ is a finite-dimensional algebra over $\C$,
all $D_i=\C$.
\end{theorem}

\begin{example}\label{ex:wedderburnsmall}
$\C[\mathfrak S_3]\cong\C\times\C\times M_2(\C)$, matching $6=1+1+4$, and $\C[\mathfrak S_4]$ is drawn in Figure~\ref{fig:wedderburn}. Over $\R$ the theorem gives products of matrix algebras over $\R$, $\C$ and Hamilton's quaternions $\mathbb H$, the only finite-dimensional real
division algebras (Frobenius, 1878): for instance $\R[\Z/3]\cong\R\times\C$, and $\R[Q_8]\cong\R^4\times\mathbb H$ for the quaternion group (Exercise~\ref{ex:rq8}). The quaternions of Volume~3, Chapter~12, are a factor of a group
algebra.
\end{example}

\begin{proposition}[the induced character]\label{prop:indchar}
If $\psi$ is the character of $W$, the character of $\operatorname{Ind}_H^GW$ is
\[
\operatorname{Ind}_H^G\psi(g)=\frac1{|H|}\sum_{\substack{x\in G\\ xgx^{-1}\in H}}\psi(xgx^{-1}).
\]
\end{proposition}

\begin{example}\label{ex:dihedral}
Let $G=D_n$ be the dihedral group of order $2n$, with rotations $r^k$ and reflections, and $H=\langle r\rangle\cong\Z/n$. Induce the character $\psi_j(r^k)=\zeta^{jk}$, $\zeta=e^{2\pi i/n}$. A reflection $s$ is conjugate into $H$ by no
element, so $\operatorname{Ind}\psi_j(s)=0$; and $\operatorname{Ind}\psi_j(r^k)=\zeta^{jk}+\zeta^{-jk}=2\cos(2\pi jk/n)$, since $r^k$ is conjugate in $H$ to itself and by a reflection to $r^{-k}$. For $0<j<n/2$ these are the
$2$-dimensional irreducible representations of $D_n$, realised by rotation by $2\pi j/n$ and a reflection of the plane (Exercise~\ref{ex:dihedralmackey}).
\end{example}

\begin{theorem}[Mackey, 1951]\label{thm:mackey}
For a set of representatives $s$ of the double cosets $HsK$,
\[
\operatorname{Res}_K\operatorname{Ind}_H^GW\cong\bigoplus_{s}\operatorname{Ind}_{K_s}^KW^{(s)}.
\]
\end{theorem}

\begin{corollary}[Mackey's irreducibility criterion]\label{cor:mackeyirr}
$\operatorname{Ind}_H^GW$ is irreducible if and only if $W$ is irreducible and, for every $s\in G\setminus H$, the representations $W^{(s)}$ and $\operatorname{Res}_{H_s}W$ of $H_s=H\cap s^{-1}Hs$ have no irreducible constituent in common.
\end{corollary}

\begin{lemma}\label{lem:omega}
Let $\chi$ be an irreducible character of degree $d$, and $C$ the conjugacy class of $g$. Then $\chi(g)$ and $\omega=|C|\chi(g)/d$ are algebraic integers.
\end{lemma}

\begin{lemma}[Burnside]\label{lem:burnsidevanish}
If, moreover, $|C|$ is prime to $d$, then either $\chi(g)=0$ or $\rho(g)$ is a scalar matrix.
\end{lemma}

\begin{proposition}\label{prop:primepowerclass}
If a finite group $G$ has a conjugacy class of size $p^k$ with $p$ prime and $k\ge1$, then $G$ is not simple.
\end{proposition}

\begin{theorem}[Burnside, 1904]\label{thm:burnsidepq}
Every group of order $p^aq^b$, with $p,q$ primes, is solvable.
\end{theorem}

\begin{theorem}[Frobenius, 1901]\label{thm:frobeniuskernel}
In a Frobenius group with complement $H$, the set $N$ of elements fixing no point, together with $1$, is a normal subgroup, with $G=NH$ and $N\cap H=\{1\}$.
\end{theorem}

\begin{exercise}[$\star$]\label{ex:doublecosets}
Show that $\langle\operatorname{Ind}_H^G1,\operatorname{Ind}_K^G1\rangle_G$ is the number of double cosets $HsK$. Deduce that $G$ acts doubly transitively on $X=G/H$ if and only if $\C^X$ is the sum of the trivial representation and one
irreducible representation.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:dihedralmackey}
In Example~\ref{ex:dihedral}, use Mackey's criterion to show that $\operatorname{Ind}\psi_j$ is irreducible if and only if $\psi_j\ne\psi_{-j}$, and find all irreducible representations of $D_n$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:rq8}
Show that $\R[Q_8]\cong\R^4\times\mathbb H$ and $\C[Q_8]\cong\C^4\times M_2(\C)$. (Use the four one-dimensional characters, which factor through $Q_8/\{\pm1\}$, and the action of $Q_8$ on $\mathbb H$ by left multiplication.)
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:heisenberg}
Let $p$ be an odd prime and $G$ the Heisenberg group of upper unitriangular $3\times3$ matrices over $\mathbb F_p$. Find its $p^2+p-1$ irreducible representations: $p^2$ of dimension $1$, and $p-1$ of dimension $p$, induced from the
abelian subgroup of matrices with zero $(1,2)$ entry.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:affinefrob}
For the affine group $G$ of $\mathbb F_q$, show that the characters $\theta_\psi$ of the proof of Theorem~\ref{thm:frobeniuskernel} are the non-trivial characters of $G/N\cong\mathbb F_q^\times$, and that $G$ has exactly one more irreducible
character, of degree $q-1$, induced from a non-trivial character of $N$.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:centrefaithful}
Show that if $G$ has a faithful irreducible representation, its centre is cyclic, and that the degree of an irreducible representation divides $[G:Z(G)]$. (For the second, apply Lemma~\ref{lem:omega} to the representation of
$G^n$ on $V^{\otimes n}$, as Tate did.)
\end{exercise}

\begin{definition}\label{def:partition}
A \emph{partition} $\lambda\vdash n$ is a sequence $\lambda_1\ge\lambda_2\ge\dots\ge\lambda_k>0$ of integers with sum $n$. Its \emph{Young diagram} is the set of cells $(i,j)$ with $1\le i\le k$ and $1\le j\le\lambda_i$, drawn as boxes, row $i$ from the top,
column $j$ from the left. The \emph{conjugate} partition $\lambda'$ lists the column lengths: $\lambda'_j=\#\{i:\lambda_i\ge j\}$. A \emph{tableau} of shape $\lambda$ is a filling $T$ of the cells with $1,\dots,n$, each used once.
\end{definition}

\begin{definition}\label{def:dominance}
For partitions $\lambda,\mu$ of $n$, $\lambda$ \emph{dominates} $\mu$, written $\lambda\trianglerighteq\mu$, if $\lambda_1+\dots+\lambda_i\ge\mu_1+\dots+\mu_i$ for every $i$ (with $\lambda_i=0$ beyond the last part).
\end{definition}

\begin{lemma}[Dominance lemma]\label{lem:dominance}
Let $T$ be a tableau of shape $\lambda$ and $T'$ one of shape $\mu$. If, for every $i$, the entries of row $i$ of $T'$ lie in different columns of $T$, then $\lambda\trianglerighteq\mu$.
\end{lemma}

\begin{lemma}\label{lem:kappa}
Let $T$ be a tableau of shape $\lambda$ and $T'$ one of shape $\mu$.
\begin{enumerate}[label=(\alph*)]
\item If $\kappa_T\{T'\}\ne0$, then $\lambda\trianglerighteq\mu$.
\item If $\lambda=\mu$, then $\kappa_T\{T'\}\in\{0,e_T,-e_T\}$; consequently, $\kappa_Tu$ is a multiple of $e_T$ for every $u\in M^\lambda$.
\end{enumerate}
\end{lemma}

\begin{theorem}[James' submodule theorem, 1978]\label{thm:james}
Let $U$ be a submodule of $M^\lambda$. Then either $U\supseteq S^\lambda$ or $U\subseteq(S^\lambda)^\perp$.
\end{theorem}

\begin{theorem}[Young, Frobenius, Specht]\label{thm:specht}
The Specht modules $S^\lambda$, for $\lambda\vdash n$, are irreducible and pairwise non-isomorphic, and every irreducible representation of $\mathfrak S_n$ is isomorphic to exactly one of them.
\end{theorem}

\begin{definition}\label{def:standard}
A tableau is \emph{standard} if its entries increase along each row (left to right) and down each column. The number of standard tableaux of shape $\lambda$ is written $f^\lambda$.
\end{definition}

\begin{theorem}\label{thm:standardbasis}
The polytabloids $e_T$, for $T$ standard of shape $\lambda$, are linearly independent. In particular $\dim S^\lambda\ge f^\lambda$.
\end{theorem}

\begin{lemma}\label{lem:insertion}
$P\leftarrow x$ is a partial standard tableau, whose shape is that of $P$ plus one corner cell. Along the bumping path, the column of the bumped entry weakly decreases from each row to the next. Given $P\leftarrow x$ and the new cell,
both $P$ and $x$ can be recovered.
\end{lemma}

\begin{theorem}[Schensted, 1961]\label{thm:schensted}
The length of the first row of $P(\sigma)$ is the length of the longest increasing subsequence of $\sigma(1),\sigma(2),\dots,\sigma(n)$.
\end{theorem}

\begin{definition}\label{def:hook}
The \emph{hook} of a cell $(i,j)$ of $\lambda$ is the cell itself, the cells to its right in row $i$ (its \emph{arm}) and the cells below it in column $j$ (its \emph{leg}). Its \emph{hook length} is
$h_{ij}=(\lambda_i-j)+(\lambda'_j-i)+1$.
\end{definition}

\begin{theorem}[Hook length formula; Frame, Robinson and Thrall, 1954]\label{thm:hook}
For $\lambda\vdash n$,
\[
f^\lambda=\frac{n!}{\prod_{(i,j)\in\lambda}h_{ij}}.
\]
\end{theorem}

\begin{theorem}[Frobenius, 1900]\label{thm:transposition}
For a transposition $\tau$ and $\lambda\vdash n$,
\[
\frac{\chi^\lambda(\tau)}{f^\lambda}=\frac1{\binom n2}\Bigl(\sum_i\binom{\lambda_i}2-\sum_j\binom{\lambda'_j}2\Bigr)=\frac1{\binom n2}\sum_{(i,j)\in\lambda}(j-i).
\]
\end{theorem}

\begin{corollary}\label{cor:conjugate}
$\chi^{\lambda'}(\tau)/f^{\lambda'}=-\chi^\lambda(\tau)/f^\lambda$, and $f^{\lambda'}=f^\lambda$.
\end{corollary}

\begin{exercise}[$\star$]\label{ex:catalan}
Show with the hook length formula that $f^{(n,n)}=\frac1{n+1}\binom{2n}n$, the Catalan number. Find a direct bijection between standard tableaux of shape $(n,n)$ and sequences of $n$ opening and $n$ closing brackets that are correctly matched.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:smalltables}
List the partitions of $4$ and compute $f^\lambda$ and $\chi^\lambda(\tau)$ for each with the hook length formula and Theorem~\ref{thm:transposition}. Match them with the rows of the character table of $\mathfrak S_4$ (Volume~3, Example~11.13). Then compute
the dimensions of the irreducible representations of $\mathfrak S_5$ and check that their squares add up to $120$.
\end{exercise}

\begin{exercise}[$\star$]\label{ex:standardrep}
Show that $M^{(n-1,1)}\cong S^{(n)}\oplus S^{(n-1,1)}$, using only the remark after Theorem~\ref{thm:specht} and dimensions. Then show with the hook length formula that $f^{(n-j,j)}=\binom nj-\binom n{j-1}$ for $0\le j\le n/2$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:youngmult}
Let $\mu\vdash n$. Show that every module map $\theta:S^\mu\to M^\mu$ is a multiple of the inclusion, and deduce that $S^\mu$ occurs exactly once in $M^\mu$ and that every other irreducible constituent $S^\lambda$ of $M^\mu$ has $\lambda\triangleright\mu$.
\end{exercise}

\begin{exercise}[$\star\star$]\label{ex:patience}
\emph{Patience sorting.} Deal the values $\sigma(1),\dots,\sigma(n)$ one at a time onto piles: each card goes on the leftmost pile whose top card is larger, or starts a new pile on the right. Show that each pile read from bottom to top is a
decreasing subsequence, that the number of piles is the length of the longest increasing subsequence, and that the tops of the piles are always the first row of the Robinson--Schensted tableau $P$. Deduce the Erdős--Szekeres theorem (1935):
every sequence of $rs+1$ distinct numbers has an increasing subsequence of length $r+1$ or a decreasing one of length $s+1$.
\end{exercise}

\begin{exercise}[$\star\star\star$]\label{ex:frobeniusdim}
Let $\lambda=(\lambda_1,\dots,\lambda_k)$ and $l_i=\lambda_i+k-i$, so $l_1>l_2>\dots>l_k\ge0$. Show that the hook lengths in row $i$ are the numbers $1,2,\dots,l_i$ with the $k-i$ numbers $l_i-l_j$, $j>i$, removed. Deduce Frobenius' formula
\[
f^\lambda=\frac{n!\prod_{i<j}(l_i-l_j)}{l_1!\,l_2!\cdots l_k!}.
\]
\end{exercise}

\begin{proposition}\label{prop:unitarytrick}
Every representation $\rho$ of $G$ is unitary for some inner product on $V$, and is a direct sum of irreducible representations.
\end{proposition}

\begin{theorem}[Schur orthogonality]\label{thm:schurorth}
Let $\rho,\sigma$ be irreducible unitary representations, of dimensions $d_\rho,d_\sigma$. Then
\[
\int_G\rho_{ij}(g)\,\overline{\sigma_{kl}(g)}\dd\mu(g)=\begin{cases}\frac1{d_\rho}\delta_{ik}\delta_{jl}&\text{if }\rho=\sigma,\\0&\text{if }\rho\not\cong\sigma.\end{cases}
\]
Consequently the characters $\chi_\rho=\operatorname{tr}\rho$ of irreducible representations are orthonormal in $L^2(G,\mu)$, and two representations with the same character are isomorphic.
\end{theorem}

\begin{definition}\label{def:schurpoly}
The \emph{Schur function} of a dominant weight $\lambda$ is $s_\lambda=a_{\lambda+\delta}/a_\delta$.
\end{definition}

\begin{theorem}[Weyl's character formula for $U(n)$, 1925]\label{thm:weylchar}
For every dominant weight $\lambda$ there is an irreducible representation $V_\lambda$ of $U(n)$ whose character on $T$ is $s_\lambda$, and every irreducible representation is isomorphic to exactly one $V_\lambda$. Its dimension is
\[
\dim V_\lambda=s_\lambda(1,\dots,1)=\prod_{1\le j<k\le n}\frac{\lambda_j-\lambda_k+k-j}{k-j}.
\]
\end{theorem}

\begin{proposition}\label{prop:powertraces}
For integers $j,k\ge1$, $\mathbb E[\operatorname{tr}U^j]=0$ and
\[
\mathbb E\bigl[\operatorname{tr}U^j\,\overline{\operatorname{tr}U^k}\bigr]=\delta_{jk}\min(k,n).
\]
\end{proposition}

